export function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  const normalized = decoded.replaceAll("\\", "/");

  if (
    !normalized ||
    normalized.startsWith("/") ||
    /^[A-Za-z]:\//.test(normalized)
  ) {
    return null;
  }

  const segments = normalized.split("/");

  if (segments.some((segment) => segment === "..")) {
    return null;
  }

  const key = segments
    .filter((segment) => segment && segment !== ".")
    .join("/");

  return key || null;
}

let decoded: string;

try {
  decoded = decodeURIComponent(value);
} catch {
  return null;
}

let traversalCheck = decoded;

while (traversalCheck.includes("%")) {
  try {
    const next = decodeURIComponent(traversalCheck);

    if (next === traversalCheck) {
      break;
    }

    traversalCheck = next;
  } catch {
    break;
  }
}

const normalized = decoded.replaceAll("\\", "/");
const normalizedTraversalCheck = traversalCheck.replaceAll("\\", "/");

if (
  !normalized ||
  normalized.startsWith("/") ||
  /^[A-Za-z]:\//.test(normalized) ||
  normalizedTraversalCheck.startsWith("/") ||
  /^[A-Za-z]:\//.test(normalizedTraversalCheck)
) {
  return null;
}

const segments = normalized.split("/");
const traversalSegments = normalizedTraversalCheck.split("/");

if (
  segments.some((segment) => segment === "..") ||
  traversalSegments.some((segment) => segment === "..")
) {
  return null;
}

const key = segments
  .filter((segment) => segment && segment !== ".")
  .join("/");

return key || null;

