const fields: string[] = [];
let index = 0;

while (index <= row.length) {
  if (row[index] === '"') {
    let value = "";
    index++;

    while (index < row.length) {
      if (row[index] !== '"') {
        value += row[index];
        index++;
      } else if (row[index + 1] === '"') {
        value += '"';
        index += 2;
      } else {
        index++;
        break;
      }
    }

    fields.push(value);
  } else {
    const start = index;
    while (index < row.length && row[index] !== ',') {
      index++;
    }
    fields.push(row.slice(start, index).trim());
  }

  if (index === row.length) {
    break;
  }
  index++;
}

return fields;

