const fields: string[] = [];
let index = 0;

while (index <= row.length) {
  if (row[index] === '"') {
    index += 1;
    let value = "";

    while (index < row.length) {
      if (row[index] !== '"') {
        value += row[index];
        index += 1;
      } else if (row[index + 1] === '"') {
        value += '"';
        index += 2;
      } else {
        index += 1;
        break;
      }
    }

    fields.push(value);
  } else {
    const fieldStart = index;
    while (index < row.length && row[index] !== ',') {
      index += 1;
    }
    fields.push(row.slice(fieldStart, index).trim());
  }

  if (row[index] === ',') {
    index += 1;
  } else {
    break;
  }
}

return fields;

