const fields: string[] = [];
let value = "";
let inQuotes = false;
let quotedField = false;

for (let index = 0; index < row.length; index += 1) {
  const character = row[index];

  if (inQuotes) {
    if (character === '"') {
      if (row[index + 1] === '"') {
        value += '"';
        index += 1;
      } else {
        inQuotes = false;
      }
    } else {
      value += character;
    }
  } else if (character === ",") {
    fields.push(quotedField ? value : value.trim());
    value = "";
    quotedField = false;
  } else if (character === '"' && value.trim() === "") {
    inQuotes = true;
    quotedField = true;
    value = "";
  } else if (!quotedField) {
    value += character;
  }
}

fields.push(quotedField ? value : value.trim());
return fields;

