  id: string;
  title: string;
};

const projectCache = new Map<string, CachedProject>();
const pendingLoads = new Map<string, Promise<CachedProject>>();

export async function getCachedProject(
  id: string,
  load: () => Promise<CachedProject>,
) {
  const cached = projectCache.get(id);
  if (cached) return cached;

  const pending = pendingLoads.get(id);
  if (pending) return pending;

  const loading = load();
  const promise = loading.then(
    (project) => {
      if (pendingLoads.get(id) === promise) {
        pendingLoads.delete(id);
        projectCache.set(id, project);
      }
      return project;
    },
    (error) => {
      if (pendingLoads.get(id) === promise) {
        pendingLoads.delete(id);
      }
      throw error;
    },
  );
  pendingLoads.set(id, promise);
  return promise;
}

export function clearProjectCache() {
  projectCache.clear();
